// Original mechanical diagrams. Every diamond represents one arbitrary new-water token.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const scatter=[[8,14],[29,8],[49,19],[70,9],[94,18],[115,8],[137,20],[17,37],[40,31],[62,42],[83,30],[107,41],[131,34],[6,59],[31,55],[54,64],[77,53],[101,63],[124,55],[144,62],[22,76],[58,80],[94,77],[133,82]];
const token=(x,y,size=5)=>`<path d="m${x} ${y-size} ${size} ${size} -${size} ${size} -${size} -${size}Z" fill="#236e9b" stroke="#124763" stroke-width="1"/>`;
const pile=(count,x,y,sx=1,sy=1)=>scatter.slice(0,count).map(([px,py])=>token(x+px*sx,y+py*sy,4)).join('');
function slots(prior,newCount,prefix,x,y,cell=36){return Array.from({length:12},(_,i)=>{const sx=x+i%4*cell,sy=y+Math.floor(i/4)*cell;return `<g><rect x="${sx}" y="${sy}" width="${cell-3}" height="${cell-3}" rx="3" fill="#f8fcfc" stroke="#829eaa"/><text x="${sx+5}" y="${sy+12}" fill="#496570" font-size="10">${i+1}</text>${i<prior?`<circle cx="${sx+cell/2}" cy="${sy+cell/2+4}" r="8" fill="url(#${prefix}-old)" stroke="#655b43" stroke-width="1.5"/>`:i<prior+newCount?token(sx+cell/2,sy+cell/2+4,8):''}</g>`;}).join('');}
export function rainMachineArt(row,{prefix=`rain-${row.id}`}={}){
 const id=prefix.replace(/[^a-zA-Z0-9_-]/g,''),open=row.cover==='open';
 return `<svg class="rp-machine-art" viewBox="0 0 400 340" role="img" aria-label="${esc(`Tray ${row.id}, ${open?'open entrance':'sealed lid'}. ${row.priorStored} already stored before this rain. New tokens: ${row.cloudRemaining} in cloud reserve, ${row.surfaceNew} on surface, ${row.storedNew} newly stored and ${row.runoffNew} in runoff collector. Twelve numbered storage slots in three rows of four.`)}"><defs><pattern id="${id}-old" width="5" height="5" patternUnits="userSpaceOnUse"><rect width="5" height="5" fill="#f4e2b5"/><path d="M0 0l5 5M-2 3l4 4M3-2l4 4" stroke="#7a6742" stroke-width="1.5"/></pattern><marker id="${id}-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="m0 0 10 5-10 5Z" fill="#526f7c"/></marker></defs><g font-family="inherit" fill="#234957"><rect x="12" y="18" width="185" height="81" rx="26" fill="#e3eff5" stroke="#8daebe" stroke-width="2"/><text x="28" y="13" font-size="15">Cloud reserve: ${row.cloudRemaining}</text>${pile(row.cloudRemaining,26,23,1,.64)}<path d="M106 102v17" stroke="#526f7c" stroke-width="2" marker-end="url(#${id}-arrow)"/><text x="16" y="137" font-size="14">Surface: ${row.surfaceNew}</text>${Array.from({length:row.surfaceNew},(_,i)=>token(119+i*22,132,6)).join('')}<path d="M22 156v130q0 7 7 7h156q7 0 7-7V156" fill="#dceaf0" stroke="#466976" stroke-width="2"/>${open?`<path d="M21 155h60m51 0h61" stroke="#466976" stroke-width="7"/><path d="M106 146v22" stroke="#526f7c" stroke-width="2" marker-end="url(#${id}-arrow)"/>`:'<rect x="18" y="149" width="178" height="10" rx="2" fill="#466976"/><path d="m98 147 16-16m-16 0 16 16" stroke="#466976" stroke-width="2"/>'}${slots(row.priorStored,row.storedNew,id,35,172,36)}<text x="25" y="314" font-size="14">Storage: 12 numbered slots</text><path d="M216 135h70v62" stroke="#526f7c" stroke-width="3" fill="none" marker-end="url(#${id}-arrow)"/><text x="239" y="126" font-size="14">Outlet</text><path d="M224 212v81q0 12 12 12h137V212" fill="#e7f1f5" stroke="#466976" stroke-width="2"/>${pile(row.runoffNew,230,215,.9,.88)}<text x="223" y="328" font-size="14">New runoff: ${row.runoffNew}</text><text x="221" y="181" font-size="12">${open?`${row.emptySlots} empty slots`: 'Solid lid: none enter'}</text></g></svg>`;
}
export function rainPlanArt(plan,{prefix=`rain-plan-${plan.trayId}`}={}){
 const id=prefix.replace(/[^a-zA-Z0-9_-]/g,''),holding=plan.route==='holding12';
 return `<svg class="rp-plan-art" viewBox="0 0 600 265" role="img" aria-label="${esc(`Planning copy from tray ${plan.trayId}: ${plan.total} source runoff tokens. ${plan.reserve} in reserve, ${plan.cup} in the holding cup, ${plan.lowPath} in the low-path collector. ${holding?'The holding cup has twelve numbered spaces in three rows of four.':'Straight channel: all sent tokens continue to the low-path collector.'}`)}"><defs><marker id="${id}-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="m0 0 10 5-10 5Z" fill="#526f7c"/></marker></defs><g font-family="inherit" fill="#234957"><text x="18" y="23" font-size="16">Copy reserve: ${plan.reserve}</text><rect x="14" y="37" width="165" height="119" rx="10" fill="#e3eff5" stroke="#829eaa"/>${pile(plan.reserve,22,48,1,1)}<path d="M185 99h42" stroke="#526f7c" stroke-width="3" marker-end="url(#${id}-arrow)"/>${holding?`<path d="M234 49v139h148V49" fill="#dceaf0" stroke="#466976" stroke-width="3"/>${slots(0,plan.cup,id,241,70,34)}<text x="233" y="217" font-size="15">Cup: ${plan.cup} of 12</text><path d="M390 99h38" stroke="#526f7c" stroke-width="3" marker-end="url(#${id}-arrow)"/><text x="393" y="78" font-size="12">Overflow</text>`:`<path d="M236 99h192" stroke="#526f7c" stroke-width="4" marker-end="url(#${id}-arrow)"/><text x="259" y="80" font-size="15">Straight channel</text><text x="259" y="126" font-size="14">Cup: 0</text>`}<path d="M438 50v131q0 10 10 10h138V50" fill="#e7f1f5" stroke="#466976" stroke-width="3"/>${pile(plan.lowPath,446,63,.9,1.2)}<text x="430" y="218" font-size="15">Low path: ${plan.lowPath}</text><text x="18" y="252" font-size="14">${plan.total} source tokens = ${plan.reserve} reserve + ${plan.cup} cup + ${plan.lowPath} low path</text></g></svg>`;
}
